-- Парсер цін: магазини, категорії, матеріали з правилами, джерела. Згенеровано tools/price-parser/seed-sql.mjs

-- одиниці виміру
insert into public.material_units (name, sort_order)
select v.name, (select coalesce(max(sort_order), 0) from public.material_units) + v.n
from (values ('пара', 1), ('100 шт', 2), ('1000 шт', 3)) as v(name, n)
where not exists (select 1 from public.material_units u where u.name = v.name);

-- категорії матеріалів
insert into public.material_categories (name, icon, sort_order)
select v.name, v.icon, (select coalesce(max(sort_order), 0) from public.material_categories where parent_id is null) + v.n
from (values ('Дерево', '🪵', 1), ('Утеплювач', '🧱', 2), ('Плівки, мембрани, стрічки', '🧻', 3), ('Вікна і двері', '🪟', 4), ('Оздоблення', '🎨', 5), ('Покрівля', '🏠', 6), ('Витратні матеріали', '🧰', 7), ('Сітки та захист', '🕸️', 8)) as v(name, icon, n)
where not exists (select 1 from public.material_categories c where c.name = v.name);

-- магазини
insert into public.suppliers (name, region, website, parser_key, parser_enabled, parse_status, notes)
select v.name, 'Київ', v.website, v.key, v.enabled, v.status, 'Інтернет-магазин будматеріалів. Ціни оновлює парсер раз на день.'
from (values
  ('Епіцентр', 'https://epicentrk.ua/', 'epicentr', true, null),
  ('ОЛДІ', 'https://oldimarket.com.ua/', 'oldi', true, null),
  ('Budia', 'https://budia.ua/', 'budia', true, null),
  ('КУБ', 'https://kub.in.ua/', 'kub', true, null),
  ('Budmaterial', 'https://budmaterial.kyiv.ua/', 'budmaterial', true, null),
  ('М2', 'https://m2.org.ua/', 'm2', true, null),
  ('Woodmax', 'https://woodmax.ua/', 'woodmax', true, null),
  ('Alba Wood', 'https://www.alba-wood.com.ua/', 'albawood', true, null),
  ('Leroy Merlin', 'https://www.leroymerlin.ua/', 'leroymerlin', false, 'Сайт захищено від автоматичного збору даних (DataDome): справжньому браузеру показує капчу після кількох сторінок. Ціни — вручну або з прайсу від магазину.'),
  ('Angio', 'https://angio.com.ua/', 'angio', false, 'Сайт не пускає програми (перевірка Cloudflare «чи ви людина»). Ціни — вручну або з прайсу від магазину.')
) as v(name, website, key, enabled, status)
where not exists (select 1 from public.suppliers s where s.parser_key = v.key);
insert into public.supplier_contacts (supplier_id, type, value, label, sort_order)
select s.id, 'website', s.website, 'Сайт', 0 from public.suppliers s
where s.parser_key is not null and s.website is not null
  and not exists (select 1 from public.supplier_contacts c where c.supplier_id = s.id);

