  ('Пензель малярний', 'Витратні матеріали', 'шт', 'Плоский малярний пензель (розміри різні). Серединна ціна за штуку.', '{"groups":["brush"],"norm":"piece","agg":"median","all":["пензел|пензл|кисть|кисти|кисточ"],"none":"макловиц|набір|набор|художн|радіатор|радиатор|щітк|щетк","min":8,"max":600}'::jsonb),
  ('Макловиця', 'Витратні матеріали', 'шт', 'Макловиця для ґрунтування й просочення. Серединна ціна за штуку.', '{"groups":["brush"],"norm":"piece","agg":"median","all":["макловиц"],"none":"набір|набор","min":20,"max":900}'::jsonb),
  ('Сітка металева, вічко до 6×6 мм (захист від гризунів)', 'Сітки та захист', 'м²', 'Зварна/ткана оцинкована сітка з вічком не більше 6×6 мм — під будинок. Ціна за м²; у пропозиціях — за рулон.', '{"groups":["mesh"],"norm":"roll_m2","cell_max":6.5,"all":["сітк|сетк","зварн|сварн|оцинк|метал|ткан|нержав|просічн|просечн|цпвс|сталев|стальн"],"none":"пластик|склосіт|стеклосет|скловолок|стекловолок|полімер|полимер|композит|москіт|москит|абразив|фасадн|затін|затен|маскув|маскир|серпянк|малярн","min":15,"max":2500}'::jsonb)
), upd as (
  update public.materials m set parse_rule = v.rule, spec = v.spec
  from v where m.name = v.name
  returning m.name
)
insert into public.materials (name, category_id, unit, spec, parse_rule)
select v.name, (select c.id from public.material_categories c where c.name = v.category order by c.parent_id nulls first limit 1), v.unit, v.spec, v.rule
from v where v.name not in (select name from upd);

